.char-blur-span {
    display: inline-block;
    filter: blur(0px);
    color: inherit;
    -webkit-text-fill-color: inherit;
}

@keyframes charBlurPulse {
    0% {
        filter: blur(0px);
        animation-timing-function: cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }
    50% {
        filter: blur(2px);
        animation-timing-function: cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }
    100% { filter: blur(0px); }
}

.is-char-hovering .char-blur-span {
    animation: charBlurPulse 0.2s;
    animation-delay: calc(var(--char-index) * 0.035s);
}

