#__framer-editorbar {
    /* https://sergeyski.com/css-color-scheme-and-iframes-lessons-learned-from-disqus-background-bug */
    color-scheme: light dark;
    overflow: hidden;
    position: fixed;
    border: none;
    z-index: calc(2147483647);
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    touch-action: manipulation;
}

@supports (height: 100dvh) {
    #__framer-editorbar {
        height: 100dvh;
    }
}

#__framer-editorbar.status_hidden {
    display: none;
}

#__framer-editorbar.status_visually_hidden {
    clip-path: circle(1px at calc(100% - 1px) calc(100% - 1px));
    z-index: calc(2147483647 - 1);
}

#__framer-editorbar.status_measuring {
    clip-path: unset;
}

html.lenis,
html.lenis body {
  height: auto;
}

.lenis:not(.lenis-autoToggle).lenis-stopped {
  overflow: clip;
}

.lenis [data-lenis-prevent],
.lenis [data-lenis-prevent-wheel],
.lenis [data-lenis-prevent-touch],
.lenis [data-lenis-prevent-vertical],
.lenis [data-lenis-prevent-horizontal] {
  overscroll-behavior: contain;
}

.lenis.lenis-smooth iframe {
  pointer-events: none;
}

.lenis.lenis-autoToggle {
  transition-property: overflow;
  transition-duration: 1ms;
  transition-behavior: allow-discrete;
}

@keyframes shimmer-Rdpc6mlp {
    0%, 0% {
        background-position: 200%;
    }
    100% {
        background-position: -100%;
    }
}
.text-shimmer-Rdpc6mlp {
    background: linear-gradient(
        120deg,
        transparent 0%,
        transparent 30.5%,
        var(--token-20608b9f-0145-4a1e-b971-ee948ebbb015, rgb(255, 255, 255)) 50%,
        transparent 69.5%,
        transparent 100%
    );
    -webkit-background-size: 200% 200%;
    -moz-background-size: 200% 200%;
    background-size: 200% 200%;
    -webkit-background-clip: text;
    -moz-background-clip: text;
    background-clip: text;
    background-repeat: no-repeat;
    animation: shimmer-Rdpc6mlp 3s linear infinite;
}
